import ModuleIntroduction from './components/ModuleIntroduction.jsx'
import React, { useMemo, useState } from 'react'
import Icon from './components/ui/Icon.jsx'
import RefreshButton from './components/ui/RefreshButton.jsx'
import './help-center.css'

const MODULES = [
  {
    id: 'collections', module: 'collections', icon: 'wallet', title: 'Cobranzas', summary: 'Revisá y confirmá los pagos de servicios con monto y forma de pago.',
    articles: [
      { title: 'Qué se incluye', body: 'El seguimiento comienza con los servicios del 14 de octubre de 2026 en adelante que tengan monto mayor a cero y forma de pago. No se incorporan servicios anteriores ni sus reprogramaciones. Un servicio dividido en varias jornadas tiene una sola cobranza compartida.' },
      { title: 'Actuales y anteriores / Futuras', body: 'El listado se divide por la fecha del servicio: Actuales y anteriores reúne los servicios de hoy y de fechas pasadas; Futuras muestra los posteriores a hoy. Se usa la fecha de Argentina y, en trabajos de varias jornadas, la primera jornada vigente. La clasificación es independiente del estado del pago: un servicio futuro ya cobrado permanece en Futuras como pago anticipado confirmado. Buscar, Estado del pago y el rango de fechas se aplican a ambos segmentos; los importes, cantidades y pendientes de cada uno reflejan esos filtros. Cada segmento tiene su propia paginación.' },
      { title: 'Avisos de pago pendiente', body: 'Las cobranzas pendientes aparecen en la campana de los roles que tienen habilitada esa categoría en Configuración, Roles y permisos, Notificaciones. Requiere acceso a Cobranzas y a los importes. Al seleccionar un aviso se abre su ficha. Consultarlo o completar el trabajo no confirma el pago: permanece pendiente hasta verificar su recepción.' },
      { title: 'Confirmar o rectificar', body: 'En Gestionar, revisá el monto y la forma de pago efectivos. Guardar corrección mantiene el estado actual del pago y permite corregir una cobranza pendiente aunque todavía falte el comprobante. Confirmar pago registra que el dinero fue recibido y retira su notificación; verificá la recepción antes de usarlo. El historial conserva los valores anteriores, la fecha, el usuario y la observación. Las correcciones posteriores de un pago confirmado conservan su confirmación. Si se cambia su medio de pago por otro distinto de efectivo, se exige un nuevo comprobante.' },
      { title: 'Comprobante de pago', body: 'Para confirmar una transferencia o un pago con débito o crédito, solicitá el comprobante al cliente y adjuntalo como imagen o PDF en la ficha de cobranza. En efectivo es opcional. Podés revisar el archivo antes de guardar; seleccionarlo no confirma el pago. El archivo y la confirmación se guardan juntos: si falla la carga, el pago sigue pendiente y podés reintentar. Los comprobantes pertenecen a la cobranza única del servicio, aunque tenga varias jornadas. Los pagos confirmados antes de incorporar esta exigencia conservan su estado y permiten adjuntar el respaldo posteriormente, sin cambiar la fecha original de confirmación.' },
      { title: 'Consultar y reemplazar comprobantes', body: 'El comprobante vigente puede abrirse desde la ficha. Con permiso para confirmar pagos podés adjuntar o reemplazar un respaldo; el archivo anterior queda conservado y su reemplazo se registra en el historial. Los archivos guardados no se eliminan desde la ficha. La consulta de versiones anteriores requiere permiso para consultar la trazabilidad. Los comprobantes tienen acceso financiero y no aparecen entre las fotos o los adjuntos técnicos del servicio.' },
      { title: 'Permisos', body: 'Administración tiene acceso completo. Consultar Cobranzas e importes y medios de pago permite ver la ficha y su comprobante vigente. Confirmar un pago habilita la confirmación y la carga o reemplazo de respaldos. Rectificar el importe y Rectificar el medio de pago se configuran por separado. Consultar trazabilidad habilita el historial y los respaldos anteriores. Cada función respeta el alcance de servicios del rol. Los permisos de adjuntos técnicos no otorgan acceso a comprobantes de pago.' }
    ]
  },
  {
    id: 'tickets', module: 'tickets', icon: 'check', title: 'Tickets', summary: 'Reclamos y solicitudes con responsable, conversación y resultado.',
    articles: [
      { title: 'Crear un ticket', body: 'En Operación → Tickets, elegí Nuevo ticket. Para reclamos buscá la cuenta por PIG, CLI o nombre. Para pedidos internos la cuenta puede ser opcional según la categoría. Elegí categoría y subcategoría; la prioridad y el área se sugieren según las reglas de Administración. Podés informar evento, zona, fecha, observaciones y adjuntos. Cada caso recibe un número propio con formato Ticket#.' },
      { title: 'Evitar duplicados', body: 'Al seleccionar una cuenta se muestran sus tickets abiertos dentro de tu alcance. Revisá el detalle: Es el mismo caso agrega tu información a la conversación y conserva tu autoría; Es un caso diferente crea otro ticket. Se vuelve a comprobar al guardar. Para fusionar casos ya creados se requiere permiso: el número principal se conserva y las referencias de los otros tickets siguen disponibles.' },
      { title: 'Gestionar y cerrar', body: 'La bandeja permite consultar Nuevos, En gestión, En espera, Resueltos y Fusionados, con búsqueda y filtros. Asigná responsable, registrá avances, reclasificá con motivo o dejá en espera con una fecha de revisión opcional. Resolver requiere un responsable y el resultado de la gestión. Reabrir conserva la cronología. Vincular un servicio de la agenda no cierra automáticamente el ticket.' },
      { title: 'Solicitudes técnicas', body: 'En el informe, Solicitar acción / seguimiento permite informar una cotización, una visita u otra acción. La solicitud se guarda junto al informe y aparece en Tickets. Los seguimientos anteriores de Agentec conservan autores, fechas y gestiones. El técnico consulta sus casos desde Tickets en su portal.' },
      { title: 'Notas y correo', body: 'Una nota interna sólo la ven los perfiles autorizados. Agregar información al caso no envía un correo. Responder al cliente, cuando el correo está habilitado, muestra el destinatario y deja el mensaje en una cola con estado visible. El modo de prueba no envía respuestas. La primera sincronización fija el punto de inicio y las siguientes incorporan sólo mensajes posteriores; no importa historia de Zammad. Los adjuntos admiten PDF, JPG, PNG y WEBP, hasta 5 archivos, 2 MB por archivo y 2,5 MB total.' },
      { title: 'Conectar el correo de soporte', body: 'En Administración → Configuración → Tickets → Correo de soporte, cargá la dirección, el área de destino y los servidores de entrada IMAP y salida SMTP. Podés usar las mismas credenciales o configurarlas por separado. Guardar mantiene el correo pausado: probá ambas conexiones y luego activá prueba u operativo. Las pruebas no envían mensajes. Procesar ahora ejecuta una sincronización; en operativo también puede enviar las respuestas pendientes y pide confirmación. La ejecución automática requiere un proceso programado. El modo de prueba usa un buzón o carpeta aislada y no envía respuestas. Los mensajes se conservan en el servidor.' },
      { title: 'Configuración y permisos', body: 'Administración → Configuración → Tickets permite definir categorías, subcategorías, prioridad, áreas, integrantes y eventos. Cada rol tiene permisos de consulta, creación, comentarios, asignación, clasificación, cierre, reapertura, fusión, correo y notas internas. Los alcances propios, por área o todos determinan qué casos puede consultar. La campana mantiene avisos de casos abiertos; abrir el aviso no resuelve el caso. Las reglas nuevas no cambian la clasificación histórica de los tickets existentes.' }
    ]
  },
  {
    id: 'start', module: 'dashboard', icon: 'dashboard', title: 'Primeros pasos', summary: 'Conocé el recorrido completo desde la planificación hasta el cierre del servicio.',
    articles: [
      { title: 'Recorrido recomendado', intro: 'Para mantener la información ordenada, conviene trabajar en este orden:', steps: ['Revisá que el abonado o cliente exista y que sus datos estén actualizados.', 'Organizá horarios, equipos, asignación de flota y guardias desde Recursos → Planificación operativa. Luego cargá los servicios en Agenda semanal; si la fecha es feriado, definí primero si será laboral o no operativa.', 'Abrí el servicio en Agenda semanal para completar o ajustar la planificación.', 'Guardá cada servicio. Los servicios quedarán disponibles en Historial y en la agenda del técnico asignado.', 'Cuando el técnico informe el resultado, revisá el estado y sus observaciones desde Historial o desde la ficha del cliente.'] },
      { title: 'Menú y pantalla completa', body: 'Los accesos diarios se agrupan en Operación y Clientes y cobranzas. Recursos reúne Colaboradores, Flota, Tipos de servicio y Planificación operativa; Administración reúne Configuración y Auditoría. Podés desplegar ambos grupos y el navegador recuerda tu elección por usuario. Sólo se muestran los módulos habilitados para tu rol; si un grupo tiene un único módulo, aparece como acceso directo. Centro de ayuda queda al pie. El botón de tres líneas de la barra superior permite contraer el menú lateral a sus iconos o volver a expandirlo. En una computadora se conserva tu elección al recargar; en el teléfono abre y cierra el menú. El icono de pantalla completa amplía la plataforma; podés volver con el mismo botón o con Escape cuando el navegador lo permita.' },
      { title: 'Notificaciones', body: 'La campana reúne las categorías de avisos habilitadas para tu rol, incluso si no tenés acceso al Resumen general. Se eligen en Configuración, Roles y permisos, seleccionando Notificaciones en Módulo. Cada categoría depende del acceso a sus datos; quitar ese acceso también desactiva sus avisos. Administrador recibe todos. El número cuenta avisos autorizados y algunos agrupan servicios. Recibir un aviso no concede permisos adicionales para resolverlo. Consultarlo no lo elimina: se actualiza cuando se resuelve su causa.' },
      { title: 'Diferencia entre PIG y CLI', body: 'Los códigos PIG identifican abonados con alarma y abono mensual. Los códigos CLI identifican clientes que recibieron un servicio pero no poseen ese abono. El código permite reconocer correctamente a la persona aunque su nombre cambie.' },
      { title: 'Qué puede hacer cada perfil', body: 'Cada rol puede tener funciones de consulta y gestión diferentes dentro de un mismo módulo. Los permisos se definen desde Configuración, incluyendo el alcance de servicios y clientes. Para ejecutar trabajo técnico también se requiere una cuenta habilitada y la asignación al servicio. Administrador conserva acceso completo.' },
      { title: 'Antes de guardar', body: 'Confirmá fecha, equipo, técnicos, horario, tipo de servicio y cliente. Dirección y contacto deben estar completos en la ficha del cliente. En una instalación de alarma también es obligatorio indicar la ubicación de la instalación.' },
      { title: 'Campos obligatorios', body: 'El asterisco rojo aparece después del nombre del campo e indica que debe completarse antes de guardar. Los campos adicionales cambian según el tipo de servicio para evitar pedir información que no corresponde.' }
    ]
  },
  {
    id: 'dashboard', module: 'dashboard', icon: 'dashboard', title: 'Resumen general', summary: 'Consultá la proyección neta de abonados, la composición de trabajos, la evolución anual y el estado de cobranzas.',
    articles: [
      { title: 'Elegir el período', body: 'Mes de análisis actualiza los gráficos y los detalles del Resumen general. La proyección neta, la composición y los detalles de altas y bajas consideran servicios completados. La evolución anual muestra el año al que pertenece el mes elegido. Cobranzas muestra el estado actual de los pagos de servicios de ese mes, aunque el trabajo todavía esté pendiente. En computadora, los seis bloques se distribuyen en tres filas alineadas; en el teléfono se apilan para facilitar su lectura.' },
      { title: 'Proyección neta de abonados', body: 'El crecimiento neto resta los retiros de alarma a las instalaciones de alarmas monitoreadas. La línea continua muestra el resultado acumulado y la línea punteada estima el cierre del mes actual según el promedio por día hábil, de lunes a viernes. Es una estimación, no una meta ni una cantidad confirmada. Para un mes cerrado se muestra el resultado real; para un mes futuro no se calcula una proyección. La tarjeta también permite consultar las altas y bajas que forman el neto.' },
      { title: 'Composición del período', body: 'El gráfico de dona distribuye los tipos de prestaciones realizados, con su cantidad y porcentaje en la leyenda. Un trabajo puede incluir más de un tipo de servicio: en ese caso, el total de prestaciones es mayor que el total de trabajos completados. Los porcentajes se calculan sobre las prestaciones, para que la distribución represente el total correctamente.' },
      { title: 'Evolución anual', body: 'El gráfico muestra las cantidades por mes con cuatro curvas: Docta en amarillo, Nobu Town en azul, Residenciales en verde y Bajas en rojo. Para el año actual aparecen los meses transcurridos; para años anteriores, los doce meses. Pasá el cursor o tocá un mes para consultar sus cantidades. Podés ocultar o mostrar cada serie desde la leyenda. También se puede recorrer con el teclado.' },
      { title: 'Estado de cobranzas del período', body: 'Las barras agrupan las cobranzas por semana según la fecha vigente del servicio o de su primera jornada no cancelada. Separan pagos confirmados, pendientes de servicios de hoy o anteriores y pendientes de servicios futuros. El importe destacado corresponde a los pendientes de hoy o anteriores dentro del mes elegido; no incluye deudas de otros meses. Los pagos confirmados conservan su estado aunque después se cancele el servicio. No representa la recaudación recibida durante ese mes. El seguimiento general comienza el 14/10/2026: los períodos sin cobertura se indican expresamente. Ver cobranzas abre el listado con las fechas del mismo mes y todos los estados de pago; las tarjetas superiores de ese módulo conservan sus totales generales. Este bloque requiere acceso a Cobranzas y a importes y medios de pago, y respeta el alcance de servicios del rol. Sin esos permisos, Evolución anual ocupa la fila completa.' },
      { title: 'Consultar y descargar el detalle', body: 'Debajo de los gráficos se encuentran las altas por ubicación y las bajas de servicio. Usá Ver para consultar los registros que forman cada total, si tu rol tiene permiso de detalle. Los botones Excel y PDF requieren permiso de exportación; generan archivos del mes elegido, ordenados por fecha, tanto en computadora como en smartphone.' },
      { title: 'Servicios pendientes', body: 'El aviso amarillo contabiliza únicamente trabajos de hoy o de días anteriores que todavía necesitan una definición. Los servicios de mañana y fechas posteriores —incluidos los controles vehiculares programados— no se cuentan hasta que llegue su fecha. En una reprogramación se considera la nueva fecha asignada. Ingresá a Historial para completar, cancelar o reprogramar los trabajos vencidos.' }
    ]
  },
  {
    id: 'weekly', module: 'weekly', icon: 'calendar', title: 'Agenda semanal', summary: 'Planificá la semana, asigná técnicos y administrá servicios por equipo.',
    articles: [
      { title: 'Elegir la semana', body: 'Seleccioná una fecha en Mostrar desde. La vista se posiciona en el día actual cuando corresponde y, desde el sábado a las 12:00, avanza automáticamente al lunes siguiente. Las barras superior e inferior permiten consultar días anteriores y posteriores. Las jornadas que ya finalizaron permanecen disponibles como consulta de solo lectura: no admiten servicios, equipos ni asignaciones nuevas. Cada trabajo reserva su tiempo estimado y no puede superponerse con otro del mismo equipo. Los trabajos breves conservan una reserva operativa mínima de 60 minutos; los turnos predeterminados vacíos que choquen con una franja ocupada dejan de mostrarse automáticamente.' },
      { title: 'Planificación mensual y anual', body: 'Abrí Planificación para consultar el mismo mes en Recursos → Planificación operativa. Allí se encuentran Horarios, Equipos, Asignación de flota y Guardias. En Agenda semanal se mantienen los servicios y las asignaciones puntuales de cada día. Los accesos disponibles dependen de los permisos de tu rol.' },
      { title: 'Jornada laboral y descanso', body: 'La jornada general se define desde Configuración → Jornada laboral; distingue ingreso, inicio de servicios y descanso, con excepciones por fecha y equipo. Los horarios sugeridos del mes se administran por separado en Planificación operativa → Horarios. La duración de un servicio cuenta sólo trabajo efectivo: con almuerzo de 13:00 a 14:00, un servicio de 12:00 con 3 horas termina a las 16:00. Agendar, mover o cancelar recalcula la disponibilidad sin modificar los horarios de otros servicios.' },
      { title: 'Trabajar en un feriado nacional', body: 'El sistema verifica automáticamente el calendario de feriados antes de habilitar servicios. En un feriado, una persona con permiso de definir feriados debe elegir Día laboral para habilitar la agenda o Día no operativo para bloquearla. La decisión queda compartida con los demás usuarios y puede modificarse sin borrar los servicios existentes.', note: 'Si la verificación del calendario no está disponible, la agenda permanece bloqueada por seguridad y muestra la opción Reintentar.' },
      { title: 'Asignar técnicos', steps: ['Buscá el día y el equipo.', 'Presioná el botón con la silueta de una persona y el signo +.', 'Marcá los técnicos que formarán el equipo.', 'Cerrá el selector. Los nombres aparecerán debajo del título del equipo.'] },
      { title: 'Agregar o editar un servicio', steps: ['Presioná Agregar servicio o seleccioná un horario disponible.', 'Elegí hora y tipo de servicio. La duración se completa con el valor del catálogo y podés ajustarla para ese trabajo particular.', 'Si elegís Instalación de alarma, indicá Docta, Nobu Town, Residencial con monitoreo o Residencial sin monitoreo. Esta última corresponde a clientes sin abono y no suma en las estadísticas de abonados.', 'Buscá el abonado o cliente por nombre, código o teléfono.', 'Sólo en Instalación de alarma, si será un abonado pero todavía no existe el PIG, presioná Reservar nuevo abonado y cargá nombre, dirección y contacto provisorios. La reserva ocupa el turno sin crear un CLI.', 'Cuando el PIG aparezca después de importar los datos, buscá la reserva y seleccioná ese PIG para vincularlo sin cambiar horario, equipo ni duración.', 'Usá Agregar cliente CLI solamente cuando sea un cliente real sin abono que deba quedar disponible para futuros servicios.', 'Completá el detalle y, si resulta útil para el técnico, adjuntá una foto de referencia desde la galería, un archivo de la computadora o la cámara.', 'Guardá el servicio.'], note: 'Los servicios se ordenan automáticamente por horario y el sistema impide que sus franjas ocupadas se superpongan dentro del mismo equipo.' },
      { title: 'Adjuntar una foto de referencia', body: 'En el formulario del servicio, usá Galería o archivo para elegir una imagen existente o Sacar foto para utilizar la cámara. Se admite una foto JPG, PNG o WebP de hasta 1 MB. La imagen queda disponible para Administración y usuarios en Agenda semanal e Historial, y para el equipo técnico asignado. También podés reemplazarla o eliminarla desde el mismo servicio.' },
      { title: 'Diferenciar planificación y tiempos reales', body: 'Existe un conflicto de agenda solamente cuando los horarios y tiempos estimados cargados por Administración se superponen. Si un servicio de hoy termina antes, el equipo queda disponible desde el siguiente cuarto de hora y podés aprovechar esa ventana siempre que el nuevo trabajo termine antes del próximo servicio programado. Si termina después de lo previsto, la demora queda registrada como una contingencia operativa, pero no prolonga la franja planificada ni genera un conflicto rojo.' },
      { title: 'Servicio listo', body: 'El check antes del número de servicio marca que su preparación está lista. El icono se marca en verde; al pasar el cursor se muestra quién lo preparó, sin agregar texto ni cambiar el fondo de la tarjeta. Podés desmarcarlo. No completa el trabajo técnico ni se aplica a controles vehiculares. Si cambian el tipo de servicio, detalle, nota interna, checklist, cliente, dirección, fecha o equipo, la preparación vuelve a revisión. Los perfiles de solo lectura no pueden cambiarla.' },
      { title: 'Guardar servicios cargados', body: 'Completá el formulario y presioná Guardar servicio. Esperá la confirmación: ese servicio se registra inmediatamente como pendiente en Agenda semanal e Historial, incluso para fechas futuras. No es necesario guardar la columna del día. Cada operación modifica sólo los registros afectados; si otra sesión cambió el mismo servicio o existe un conflicto de horarios, se rechaza el guardado y el formulario permanece abierto para revisar los datos.' },
      { title: 'Campos adicionales según el servicio', body: 'Forma de pago, Monto, Abono mensual y Formulario se habilitan solamente cuando corresponden al tipo de servicio. Forma de pago permite Efectivo, Transferencia, Débito, Crédito, A confirmar o No aplica. Monto aparece al elegir una forma de pago, se muestra con el signo $ y separadores de miles, y es obligatorio salvo con A confirmar; con No aplica no se solicita. En Instalación de alarma, el abono mensual se habilita únicamente para una instalación Residencial con monitoreo y también se muestra con el signo $ y separadores de miles. Formulario ofrece Completo o Incompleto (Abonado completa a mano), tanto en Instalación de alarma como en Cambio de titularidad.' },
      { title: 'Eliminar o reasignar un servicio', body: 'Usá el botón rojo del servicio para eliminarlo. El botón de traslado permite elegir otro equipo del mismo día o una fecha diferente. Si cambiás la fecha, el servicio vuelve a estado Pendiente como una reprogramación. En ambos casos se conservan sus datos y Agenda semanal e Historial se actualizan juntos.' },
      { title: 'Guardias de los sábados', body: 'La rotación anual se define desde Recursos → Planificación operativa → Guardias. Cada sábado puede corregirse manualmente como excepción sin alterar el orden general. Si el técnico de guardia recibe un servicio el viernes entre las 16:00 y las 20:00, el sistema interpreta que adelantó su guardia: bloquea cualquier nuevo equipo, técnico o servicio del sábado y muestra una leyenda informativa.' },
      { title: 'Conflicto de guardia adelantada', body: 'Si el sábado ya tenía un servicio real cuando se detecta la guardia adelantada del viernes, el sistema no lo elimina. Muestra una advertencia para que Administración revise el conflicto y decida cómo resolverlo.' },
      { title: 'Servicios reprogramados y estados', body: 'Una reprogramación confirmada desde Historial se incorpora al nuevo día y conserva cliente, servicio, horario, equipo y técnicos. En Agenda semanal, cada tarjeta muestra su estado vigente —Pendiente, Completado, Cancelado, Reprogramado o Requiere revisión— junto al tipo de servicio con el mismo color utilizado en Historial, sin necesidad de abrir el trabajo. No reemplaza otros trabajos, salvo que encuentre el mismo cliente en el mismo equipo y horario.' }
    ]
  },
  {
    id: 'operationalPlanning', module: 'operationalPlanning', icon: 'calendar', title: 'Planificación operativa', summary: 'Organizá horarios, equipos, asignación de flota y guardias desde Recursos.',
    articles: [
      { title: 'Acceder y elegir el período', body: 'Abrí Recursos → Planificación operativa. Elegí el mes y la pestaña que necesitás: Horarios, Equipos, Asignación de flota o Guardias. El acceso Planificación de Agenda semanal abre el mes que estabas consultando. Guardias organiza el año correspondiente. Sólo se muestran las opciones autorizadas para tu rol.' },
      { title: 'Horarios sugeridos del mes', body: 'En Horarios, definí las franjas sugeridas para los espacios vacíos. Podés agregar períodos con una fecha de inicio dentro del mes; los servicios que ya tienen horario conservan su programación. Agregar o actualizar período modifica el borrador y Guardar horarios confirma los cambios. Los períodos pasados quedan protegidos. Esta opción no reemplaza Configuración → Jornada laboral, donde se definen los límites de la jornada y el descanso.' },
      { title: 'Conformar los equipos del mes', body: 'En Equipos, revisá la composición mensual antes de guardarla. La sugerencia considera los técnicos y vehículos disponibles y rota compañeros y salidas individuales; podés ajustarla y agregar equipos. Al guardar se actualizan los equipos pendientes que conservan la dotación mensual. Se mantienen las excepciones diarias, las guardias y los equipos con trabajos iniciados o cerrados. Historial de cambios conserva la composición anterior, la nueva, la fecha y la persona responsable.' },
      { title: 'Asignar responsables de flota', body: 'En Asignación de flota, elegí el responsable predeterminado de cada unidad y guardá la asignación mensual. La sugerencia se coordina con los equipos y el historial de responsables. Podés indicar un reemplazo para un viernes puntual sin cambiar el resto del mes. Los controles semanales se programan los viernes a las 15:45 y su generación requiere el permiso correspondiente. Si una unidad no se utilizará esa semana, una persona autorizada puede omitir el control desde Agenda semanal. Historial de cambios permite consultar las asignaciones anteriores y nuevas.' },
      { title: 'Organizar las guardias del año', body: 'En Guardias, definí el orden anual de rotación de técnicos. El ciclo comienza el primer sábado y se repite durante el año. Historial de cambios conserva la rotación anterior, la nueva, la fecha y la persona responsable. Las excepciones de un sábado y las guardias adelantadas se consultan en Agenda semanal.' },
      { title: 'Consulta, edición y permisos', body: 'Consultar y modificar cada pestaña son permisos distintos. El traslado de estas funciones conserva los permisos existentes: no otorga nuevas facultades ni cambia las asignaciones guardadas. Los meses finalizados conservan las restricciones de edición. Antes de salir de un formulario con cambios, guardalos o descartalos según corresponda.' }
    ]
  },
  {
    id: 'daily', module: 'weekly', icon: 'agenda', title: 'Servicios y vista previa', summary: 'Editá los servicios y compartí la planificación desde Agenda semanal.',
    articles: [
      { title: 'Cargar la agenda de una fecha', body: 'Elegí la fecha de trabajo. La agenda carga la planificación semanal y los servicios reprogramados de ese día. Podés agregar trabajos de último momento sin perder los ya registrados mientras la jornada no haya finalizado. Las fechas pasadas quedan bloqueadas en las agendas y se consultan o corrigen desde Historial. Los domingos permanecen bloqueados por ser días no operativos. Si es feriado, primero debe existir una definición de Día laboral; cuando se define como Día no operativo tampoco admite equipos, técnicos ni servicios.' },
      { title: 'Completar un servicio', steps: ['Ingresá la hora.', 'Seleccioná el tipo de servicio.', 'Buscá y elegí el abonado o cliente.', 'Revisá dirección, contacto y observaciones.', 'Si es una instalación de alarma, elegí la ubicación y completá los datos adicionales habilitados.', 'Si ayuda a identificar el trabajo, adjuntá una foto de referencia desde un archivo, la galería o la cámara.'], note: 'En Vista previa, Copiar agenda y la agenda técnica sólo se informa la forma de pago cuando es Efectivo —junto con el monto— y el Formulario cuando está Incompleto. El abono mensual y las demás opciones quedan para la gestión administrativa.' },
      { title: 'Reserva PIG o cliente nuevo', body: 'Reservar nuevo abonado se habilita únicamente al seleccionar Instalación de alarma. Si será un nuevo abonado y todavía no fue creado en SoftGuard, cargá datos provisorios y vinculá después el PIG importado: no se crea ningún CLI residual y el turno conserva su identidad. Dos personas pueden tener el mismo nombre; una coincidencia por nombre no vincula automáticamente una cuenta existente. Usá Agregar cliente CLI sólo para una persona que realmente será cliente sin abono. Para una cuenta existente, corregí sus datos desde Abonados y clientes.' },
      { title: 'Guardar y consultar', body: 'Guardá cada servicio desde su formulario. Vista previa, en la cabecera de cada fecha, permite consultar la planificación sin modificar servicios. Los técnicos acceden a sus trabajos desde su propia cuenta; no es necesario copiar ni enviar la agenda. Los servicios a confirmar no se incluyen en la vista previa.' },
      { title: 'Mover un servicio y consultar su estado', body: 'Presioná Reasignar en el bloque de acciones del servicio y elegí otro equipo. Se conservan todos los datos y la lista vuelve a ordenarse por horario. La ficha muestra también si el servicio está Pendiente, Completado, Cancelado, Reprogramado o Requiere revisión.' }
    ]
  },
  {
    id: 'history', module: 'history', icon: 'history', title: 'Historial', summary: 'Consultá trabajos y actualizá su estado sin perder el seguimiento.',
    articles: [
      { title: 'Buscar registros', body: 'Buscá por cliente, servicio o técnico. La búsqueda no distingue mayúsculas ni tildes: “instalacion” encuentra “Instalación”.' },
      { title: 'Cómo se ordena la tabla', body: 'La tabla muestra primero todos los servicios pendientes, desde la fecha más antigua a la más nueva y, dentro de cada día, desde el horario más temprano al más tarde. Después aparecen los servicios completados y los demás estados. La columna Hora evita tener que consultar otra agenda.' },
      { title: 'Gestionar un servicio', body: 'Presioná Gestionar para ver sus datos y la foto de referencia, si fue adjuntada. Desde allí podés cargar, reemplazar o eliminar esa foto, marcar el servicio como completado, devolverlo a pendiente, cancelarlo, reprogramarlo, editar información permitida o eliminar el registro. El permiso de finalización anticipada permite marcarlo como completado aunque todavía no haya llegado su horario; la agenda del técnico continúa respetando la fecha y hora programadas.' },
      { title: 'Estados disponibles', body: 'Pendiente significa que todavía requiere una definición. Completado confirma que el trabajo se realizó. Cancelado indica que no se realizará. Reprogramado mueve el servicio a otra fecha.' },
      { title: 'Reprogramar correctamente', steps: ['Abrí Gestionar.', 'Elegí una fecha futura.', 'Presioná Reprogramar.', 'Revisá la nueva fecha en Agenda semanal.'], note: 'El servicio se quita del día original y se incorpora una sola vez en la fecha nueva.' },
      { title: 'Retiro de equipo', body: 'Cuando un retiro de equipo se marca como completado, representa una baja de servicio. Si el cliente era abonado PIG, su registro pasa a la condición de cliente CLI conservando su información y muestra el código PIG anterior para mantener la trazabilidad. Las bajas confirmadas desde el 20 de octubre de 2026 generan un recordatorio para dar de baja la cuenta en SoftGuard. Abrir o cerrar el aviso no lo resuelve.' },
      { title: 'Gestión múltiple', body: 'Seleccioná varios registros y presioná Gestionar selección para aplicar el mismo estado a todos. Antes de confirmar, verificá que todos deban recibir exactamente el mismo cambio.' }
    ]
  },
  {
    id: 'map', module: 'map', icon: 'map', title: 'Mapa', summary: 'Consultá abonados, concentración y zonas rojas de referencia.',
    articles: [
      { title: 'Mapa de calor y puntos', body: 'El mapa de calor muestra la concentración de abonados vigentes con ubicación disponible. Puntos por abonado permite seleccionar una cuenta; los números agrupan cuentas que comparten coordenadas. Los filtros de búsqueda, zona, localidad, barrio y calidad modifican los abonados mostrados. Encuadrar ajusta la vista a las ubicaciones filtradas.' },
      { title: 'Zonas rojas', body: 'Elegí una de las tres vistas: Mapa de calor, Puntos por abonado o Zonas rojas. Se muestra únicamente la vista seleccionada. Zonas rojas presenta las áreas del mapa comunitario compartido con sus límites, nombres y colores originales. Tocá un área para consultar su nombre, o recorré las áreas con Tab y abrí el detalle con Enter o Espacio. Encuadrar zonas muestra todas las áreas. Los filtros y el listado de abonados vuelven a aparecer al elegir calor o puntos y conservan tu búsqueda.' },
      { title: 'Fuente de las zonas', body: 'Ver mapa original abre la fuente en Google My Maps. La fecha visible corresponde a la copia incorporada a la app; no se sincroniza automáticamente. Se incluyen las áreas delimitadas en la fuente, sin transformar los marcadores de incidentes en zonas. Consultar esta capa requiere el mismo permiso de acceso a Mapa.' }
    ]
  },
  {
    id: 'accounts', module: 'accounts', icon: 'accounts', title: 'Abonados y clientes', summary: 'Administrá datos comerciales y evitá registros duplicados.',
    articles: [
      { title: 'Crear un registro', body: 'Usá Nuevo cliente para cargar una persona sin abono. Código, nombre, calle o dirección y teléfono o contacto son obligatorios y están identificados con un asterisco rojo. El sistema asignará un código CLI.' },
      { title: 'Editar datos', body: 'Presioná el lápiz. Se abrirá un formulario donde podés actualizar nombre, dirección, localidad, provincia y teléfono. El nombre se guarda en mayúsculas para mantener una presentación uniforme.' },
      { title: 'Registrar la baja en SoftGuard', body: 'Desde el 20 de octubre de 2026, las bajas de abonados confirmadas en la agenda generan un aviso pendiente para actualizar SoftGuard. Abrilo desde la campana o consultá la ficha del cliente CLI para ver el PIG anterior. Primero realizá la baja en SoftGuard; después, con el permiso Registrar baja realizada en SoftGuard, verificá la cuenta indicada y registrá que la gestión está hecha. Se conserva quién la registró y cuándo, y el aviso se retira para todos los usuarios. La agenda no modifica SoftGuard automáticamente. Recibir estos avisos se configura en la categoría de actualización de abonados; el permiso para resolverlos se configura por separado.' },
      { title: 'Abonados por ubicación', body: 'El Resumen general muestra la cartera actual en barras horizontales para Docta, Nobu Town y Residenciales / otras zonas, con cantidad y porcentaje. Usa las mismas cuentas activas y clasificación del mapa, sin duplicados, bajas ni cuentas excluidas. No cambia con el mes de análisis y respeta el alcance y permiso de consulta de cuentas. Las altas y bajas del mes se consultan y exportan desde el bloque Movimientos del período.' },
      { title: 'Cuentas PIG excluidas del conteo', body: 'En Editar registro, activá Excluir del conteo de abonados para cuentas sin abono. Las que indican AUTOMONITOREO en su nombre se excluyen automáticamente; podés ajustar esa clasificación con permiso para editar clientes. La cuenta conserva su código PIG, servicios, historial y seguimiento de CCTV, pero no integra la cartera usada en el porcentaje del resumen ni el mapa de abonados. La selección manual se conserva al volver a importar. El total de registros incluye también estas cuentas y los clientes CLI.' },
      { title: 'Seguimiento de Servicio de CCTV', body: 'Con el permiso correspondiente, activá Servicio de CCTV en un abonado o cliente para incluirlo en el seguimiento. Los roles con alcance CCTV consultan únicamente las cuentas marcadas y sus servicios autorizados. El alcance se define en Configuración y es independiente del nombre del rol. La selección se conserva cuando volvés a importar la base desde SoftGuard.' },
      { title: 'Ver el historial de un cliente', body: 'Presioná Ver historial en la ficha del abonado o cliente. Se muestran todos sus servicios del más reciente al más antiguo, con fecha, hora, estado, técnicos, observación de agenda y la observación informada por el técnico.' },
      { title: 'Cómo leer una observación técnica', body: 'Cuando un técnico informa un servicio, su nota aparece identificada con su nombre, por ejemplo “Santos indicó”. Esta información ayuda a preparar futuras visitas sin confundirla con el detalle cargado por Administración.' },
      { title: 'Evitar duplicados', body: 'Antes de crear un cliente, buscalo por nombre, código o dirección. Si encontrás registros parecidos, revisá sus datos antes de continuar. No crees un CLI si la persona ya tiene un código PIG.' },
      { title: 'Eliminar un registro', body: 'Un abonado o cliente no puede eliminarse mientras tenga servicios vinculados. Esto protege su historial. Corregí o fusioná el registro correspondiente en lugar de eliminar información relacionada.' },
      { title: 'Importar abonados', body: 'Usá Importar abonados para actualizar la base de clientes PIG. Si el archivo no contiene un campo obligatorio, el sistema lo completa con “-” para mantener el registro utilizable. Revisá el archivo antes de confirmar y evitá modificar manualmente los códigos.' }
    ]
  },
  {
    id: 'technician', module: 'agenda', icon: 'users', title: 'Perfil técnico', summary: 'Informá servicios y consultá antecedentes útiles desde el teléfono o la computadora.',
    articles: [
      { title: 'Servicios asignados', body: 'Agenda técnica muestra todos los servicios vencidos que sigan pendientes, además de los trabajos de hoy y mañana, evitando anticipar el resto del mes. Los trabajos en domicilio deben resolverse en el orden indicado: la dirección y el contacto del siguiente se habilitan después de informar el estado del servicio actual. Los controles vehiculares son tareas autónomas: no poseen dirección ni contacto y se habilitan desde su propia fecha y hora. Si el viernes es un feriado definido como no operativo, el control pasa automáticamente al último día operativo anterior, incluso ante feriados consecutivos. Un control vehicular vencido permanece visible y disponible para cargar foto y kilometraje; los demás trabajos pueden consultarse, pero sus domicilios y contactos permanecen ocultos hasta completarlo.' },
      { title: 'Marcar un servicio como completado', steps: ['Presioná Marcar completado.', 'Cargá la observación técnica obligatoria con el trabajo realizado y cualquier dato útil para futuras visitas.', 'Presioná Continuar.', 'Revisá el mensaje de confirmación y elegí Sí, confirmar estado.'], note: 'Puede completarse desde su fecha y hora programadas o posteriormente si quedó vencido. Al confirmar se registra la hora real y, si terminó antes de lo previsto, la agenda libera al equipo desde el siguiente cuarto de hora. La observación también es obligatoria al solicitar una reprogramación o informar una cancelación. El control vehicular es la excepción: requiere foto interior y kilometraje, pero su observación es opcional.' },
      { title: 'Consultar la foto de referencia', body: 'Si Administración adjuntó una imagen al servicio, aparece debajo del nombre del cliente. Tocala para verla en tamaño completo. La foto sólo está disponible para los técnicos asignados a ese trabajo y sirve como apoyo para reconocer el lugar, el equipo o la tarea antes de la visita.' },
      { title: 'Consultar mi historial', body: 'Abrí Historial desde el menú del perfil técnico. La barra de búsqueda encuentra por cliente, código, servicio, fecha o detalle dentro de los trabajos que informaste.' },
      { title: 'Consultar antecedentes del cliente', body: 'Dentro de un servicio habilitado, presioná Ver historial del cliente. La consulta es de solo lectura y muestra notas de agenda y observaciones técnicas anteriores para ayudarte a preparar la visita.' },
      { title: 'Menú del técnico', body: 'En smartphone, abrí el menú desplegable con el botón de tres líneas. En una computadora, los módulos autorizados se presentan en la navegación lateral igual que en los demás perfiles.' }
    ]
  },
  {
    id: 'mobile', icon: 'menu', title: 'Uso desde smartphone', summary: 'Usá las funciones principales en una pantalla pequeña sin perder información.',
    articles: [
      { title: 'Abrir y cerrar el menú', body: 'Presioná el botón de tres líneas para mostrar los módulos y tocá fuera del panel para cerrarlo. El contenido queda bloqueado mientras el menú está abierto para evitar acciones accidentales.' },
      { title: 'Formularios y ventanas', body: 'Los campos, botones y ventanas se reorganizan automáticamente en una columna. Desplazate dentro de la ventana cuando el formulario sea largo; no es necesario alejar el zoom del navegador.' },
      { title: 'Descargar Excel o PDF', body: 'Los botones Excel y PDF generan el archivo también en smartphone. Según el navegador, la descarga puede aparecer en Descargas, Archivos o en el menú para compartir.' },
      { title: 'Crear un acceso directo', body: 'Usá la opción Agregar a pantalla de inicio del navegador. El acceso directo utiliza el ícono del búho de Agenda Pignus y abre la plataforma directamente.' },
      { title: 'Cerrar sesión', body: 'Usá Cerrar sesión cuando termines, especialmente en un dispositivo compartido. La notebook donde se desarrolló el sistema no necesita estar encendida: la aplicación funciona en Vercel y los datos se guardan en la base remota.' }
    ]
  },
  {
    id: 'employees', module: 'employees', icon: 'users', title: 'Colaboradores', summary: 'Gestioná colaboradores, accesos y disponibilidad.',
    articles: [
      { title: 'Crear o editar un colaborador', body: 'Cargá nombre y apellido por separado, rol, teléfono y correo. El nombre completo se utiliza en los demás módulos; en vistas con poco espacio puede mostrarse solamente el nombre.' },
      { title: 'Activar o desactivar', body: 'Un colaborador activo puede aparecer para asignaciones según su rol. Al desactivarlo deja de estar disponible y su sesión se cierra, pero sus trabajos anteriores permanecen registrados.' },
      { title: 'Cambiar el rol', body: 'Elegí un rol existente. Si el nombre de ese rol cambia en Configuración, se actualizará en Colaboradores sin perder la relación ni los permisos.' },
      { title: 'Eliminar', body: 'No elimines un colaborador que tenga trabajos asignados. Primero reasigná sus servicios o desactivalo para conservar correctamente el historial.' }
    ]
  },
  {
    id: 'services', module: 'services', icon: 'tools', title: 'Tipos de servicio', summary: 'Mantené actualizado el catálogo utilizado por todas las agendas.',
    articles: [
      { title: 'Crear o editar un tipo', body: 'Definí un nombre claro y una descripción breve. Los cambios de nombre se reflejan en las opciones del sistema sin perder la identidad del servicio.' },
      { title: 'Desactivar o eliminar', body: 'Si un servicio dejó de ofrecerse, es preferible marcarlo inactivo. Los servicios usados en agendas o historial no deben eliminarse porque forman parte de registros anteriores.' },
      { title: 'Tiempo estimado por servicio', body: 'Cada tipo de servicio posee una duración predeterminada expresada en horas y minutos. Cuando cambia ese valor, también se actualizan los servicios pendientes que todavía utilizaban el predeterminado anterior. Un tiempo ajustado manualmente por cantidad de equipos, cableado u otra complejidad se conserva únicamente para ese trabajo.' },
      { title: 'Instalación de alarma', body: 'Este tipo posee requisitos especiales. Al programarlo debe indicarse la ubicación de la instalación para que las estadísticas gerenciales puedan clasificarla correctamente.' }
    ]
  },
  {
    id: 'vehicles', module: 'vehicles', icon: 'vehicle', title: 'Flota', summary: 'Administrá la flota y sus datos identificatorios.',
    articles: [
      { title: 'Registrar un vehículo', body: 'Presioná Nuevo vehículo y completá Marca, Modelo, Año, Kilometraje y Matrícula. La matrícula se guarda en mayúsculas y no puede repetirse.' },
      { title: 'Cargar y consultar el seguro', body: 'Con permiso de gestionar seguros, podés adjuntar el seguro vigente en PDF —hasta 3 MB— e indicar su fecha de vencimiento. El archivo queda protegido por la sesión. Los técnicos lo descargan desde Flota; cuando vence, el Resumen general identifica la unidad y solicita gestionar el PDF actualizado con el área administrativa.' },
      { title: 'Control semanal de limpieza y kilometraje', body: 'El técnico responsable recibe los viernes a las 15:45 un servicio interno de 15 minutos. Puede realizarlo antes de esa hora cuando ya haya finalizado todos los demás servicios programados para ese día. No requiere abonado, cliente, reserva PIG, dirección, contacto ni observación: para completarlo debe informar un kilometraje superior al último registrado y adjuntar una foto del interior. El responsable se define para todo el mes, pero desde Recursos → Planificación operativa → Asignación de flota puede elegirse un reemplazo para un viernes puntual ante una contingencia. Si el vehículo no se utilizará esa semana, una persona con permiso de omitir controles puede hacerlo desde Agenda semanal y el técnico no tendrá que realizarlo. Al confirmar un control vigente, el kilometraje del vehículo se actualiza automáticamente y Administración puede consultar la foto desde el detalle del Historial. Si queda vencido, bloquea el domicilio y el contacto de la agenda siguiente —incluidos sábado y lunes— hasta que sea completado; no puede omitirse cancelándolo o solicitando una reprogramación.' },
      { title: 'Editar los datos', body: 'Usá el botón de edición de la fila correspondiente para corregir cualquiera de los cinco campos y guardá los cambios.' },
      { title: 'Eliminar de la flota', body: 'Usá el botón rojo de la fila y confirmá la eliminación. El registro dejará de formar parte de la flota disponible.' }
    ]
  },
  {
    id: 'settings', module: 'settings', icon: 'settings', title: 'Configuración', summary: 'Definí las funciones y el alcance de cada rol, módulo por módulo.',
    articles: [
      { title: 'Editar un rol', body: 'Podés cambiar su nombre y descripción. Los colaboradores vinculados conservarán el mismo rol y verán el nuevo nombre.' },
      { title: 'Asignar permisos', body: 'Seleccioná un rol y un módulo. Tildá o destildá cada función y presioná Guardar rol para aplicar todos los cambios juntos. Las opciones en gris explican qué requisito falta. Una función compartida, como Listo o adjuntar archivos, tiene el mismo permiso desde todas sus pantallas. Los permisos actuales se conservan hasta guardar una modificación.' },
      { title: 'Revisar la vista previa del rol', body: 'Antes de guardar, abrí Vista previa del rol. Recorré el menú habilitado, consultá las funciones disponibles y revisá ejemplos de las notificaciones que recibiría. También podés consultar los accesos desactivados y el alcance de los datos. Si el rol permite trabajo técnico, probá la habilitación individual del colaborador para ver cuándo aparece Mis servicios. La vista previa usa el borrador actual, no modifica datos ni cambia tu sesión. Volver a configurar conserva el borrador para seguir ajustándolo; Guardar rol aplica los cambios.' },
      { title: 'Elegir las notificaciones del rol', body: 'Seleccioná Notificaciones en Módulo y elegí las categorías que debe recibir: cobranzas, reservas, pendientes de hoy, confirmaciones, reprogramaciones, atrasados, seguros, actualización de abonados y recuperación de acceso. Las categorías sin acceso a sus datos aparecen en gris. Podés apagar un aviso y conservar el permiso de consultar o gestionar su módulo. Guardá el rol para aplicar la selección a sus usuarios. Administrador conserva todos los avisos.' },
      { title: 'Dependencias entre funciones', body: 'Al quitar un requisito se desactivan automáticamente las funciones que dependen de él. Volver a tildarlo no reactiva esas funciones: elegilas nuevamente. Si una función admite acceso desde varios módulos, sigue habilitada mientras conserve al menos una entrada autorizada. Iniciar y completar un servicio son permisos separados, porque un compañero puede haber iniciado el trabajo.' },
      { title: 'Alcance y delegación', body: 'Definí qué servicios puede consultar el rol y sobre cuáles puede actuar: todos, sólo asignados o sólo cuentas con seguimiento CCTV. Las acciones siempre quedan dentro del alcance de consulta. Los clientes pueden limitarse a los vinculados a sus servicios. Sólo podés conceder permisos y alcances que tu propio rol tiene; el último administrador activo permanece protegido.' },
      { title: 'Cambios durante una sesión', body: 'Los permisos se actualizan también para quienes ya tienen la app abierta. Si se retira una función necesaria, un formulario abierto puede dejar de permitir el guardado. Cuando otra persona modifica el mismo rol, el sistema conserva tu borrador y solicita revisar la versión actual antes de guardar.' }
    ]
  },
  {
    id: 'audit', module: 'audit', icon: 'audit', title: 'Auditoría', summary: 'Revisá quién realizó cambios importantes y qué información fue afectada.',
    articles: [
      { title: 'Consultar movimientos', body: 'Filtrá por acción o buscá un usuario, entidad o registro. Presioná Ver detalle para comparar la información anterior con la posterior. El módulo conserva y muestra únicamente los 100 movimientos más recientes para mantener un funcionamiento ágil.' },
      { title: 'Cuándo usarla', body: 'Consultá Auditoría cuando necesites saber quién creó, modificó o eliminó un dato, o cuando una agenda ya no coincida con lo esperado.' },
      { title: 'Qué no hace', body: 'Auditoría sirve para revisar movimientos; no modifica ni recupera datos por sí misma. Luego de identificar el cambio, realizá la corrección desde el módulo correspondiente.' }
    ]
  }
]

const FAQ = [
  ['¿Dónde están los horarios, equipos, vehículos y guardias?', 'Ahora se administran desde Recursos → Planificación operativa. El acceso Planificación de Agenda semanal abre el mes consultado. Las pestañas y acciones visibles dependen de los permisos de tu rol.'],
  ['¿Qué hago si marqué un servicio como completado por error?', 'Abrí el registro desde Historial y presioná Marcar pendiente. El servicio volverá a requerir una definición.'],
  ['¿Puedo agregar un servicio durante el mismo día?', 'Sí. Podés hacerlo desde Agenda semanal. Se conservarán los trabajos existentes y se ordenará por horario.'],
  ['¿Qué ocurre cuando reprogramo?', 'El servicio se mueve a la nueva fecha y conserva sus datos. No queda duplicado en el día original.'],
  ['¿Cómo cambio un servicio de equipo?', 'Usá el botón de traslado del servicio y elegí el equipo de destino. No es necesario eliminarlo ni cargarlo nuevamente.'],
  ['¿Cómo ve el técnico un servicio nuevo?', 'Guardá el servicio desde Agenda semanal. El técnico asignado podrá consultarlo con su propio acceso; no hace falta copiar ni enviar la agenda.'],
  ['¿Qué significa “No aplica” en Forma de pago?', 'Indica que ese servicio no requiere registrar un medio de pago. Al elegirlo, el campo Monto no se muestra ni se exige.'],
  ['¿Qué hago si la fecha es domingo o feriado?', 'Los domingos permanecen bloqueados y no admiten servicios. En un feriado, una persona con permiso de definir feriados debe elegir Día laboral para habilitar la agenda o Día no operativo para bloquearla. Los perfiles con acceso de consulta pueden ver la decisión.'],
  ['¿Por qué el sábado dice que el técnico adelantó el servicio?', 'Ese técnico tiene un servicio el viernes entre las 16:00 y las 20:00 y el sistema lo tomó como guardia adelantada. Por eso no ofrece otro turno el sábado por la mañana.'],
  ['¿Por qué no puedo eliminar una persona, cliente o servicio?', 'El registro puede estar vinculado a trabajos anteriores. La restricción evita perder información importante; en esos casos conviene desactivarlo o corregirlo.'],
  ['¿Qué significa “cambios guardados desde otra sesión”?', 'Otra pestaña o usuario guardó información después de que abriste la pantalla. Recargá la página antes de seguir para trabajar con la versión más reciente.'],
  ['¿Cuánto tiempo permanecen los avisos verdes?', 'Los mensajes de confirmación desaparecen automáticamente después de algunos segundos. También podés cerrarlos de inmediato con la cruz.'],
  ['¿Por qué un sábado aparece sin técnico?', 'Es intencional: trabaja una sola persona y la guardia rota. Si no fue adelantada el viernes, el técnico debe seleccionarse manualmente.'],
  ['¿Dónde corrijo la dirección o el teléfono de un cliente?', 'En Abonados y clientes. Así el cambio queda disponible para las próximas agendas.'],
  ['¿Dónde veo las observaciones de visitas anteriores?', 'En Abonados y clientes, presioná Ver historial. El técnico también puede consultar esos antecedentes en modo lectura desde su servicio asignado.'],
  ['¿Por qué el técnico no ve la dirección del próximo servicio?', 'Los trabajos se habilitan en orden. Debe informar primero el estado del servicio anterior para acceder a la dirección y el contacto del siguiente.'],
  ['¿La notebook debe quedar encendida para usar Agenda Pignus?', 'No. La aplicación está publicada en Vercel y utiliza una base de datos remota, por lo que funciona aunque la notebook esté apagada.']
]

const TECHNICIAN_FAQ = [
  ['¿Por qué no veo la dirección del próximo servicio?', 'Los trabajos en domicilio se habilitan en orden. Informá primero el estado del servicio anterior para acceder a la dirección y el contacto del siguiente.'],
  ['¿Cuándo puedo completar un servicio?', 'Desde la fecha y hora programadas. Si quedó vencido, seguirá visible hasta que informes su estado.'],
  ['¿La observación técnica es obligatoria?', 'Sí, para completar, cancelar o solicitar la reprogramación de un servicio. En el control vehicular es opcional porque se exigen la foto interior y el kilometraje actualizado.'],
  ['¿Dónde veo la foto de referencia?', 'Cuando el servicio tiene una foto adjunta, aparece debajo del nombre del cliente. Tocala para abrirla en tamaño completo.'],
  ['¿Cómo consulto trabajos anteriores?', 'Abrí Historial y buscá por cliente, código, servicio, fecha o detalle. Allí aparecen los servicios cuyo estado ya informaste.'],
  ['¿Dónde consulto antecedentes del cliente?', 'Dentro de un servicio habilitado, presioná Ver historial del cliente. La información es de solo lectura.'],
  ['¿Cómo descargo el seguro de un vehículo?', 'Abrí Flota y presioná Descargar PDF en la unidad correspondiente. Si figura No disponible, solicitá el documento actualizado a Administración.'],
  ['¿Qué hago si estoy sin conexión?', 'La agenda visible se conserva, pero esperá a recuperar conexión antes de informar un estado para asegurar que el cambio se guarde.']
]

const TECHNICIAN_MODULE_IDS = new Set(['technician', 'vehicles', 'mobile'])

const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()

export function HelpShell({ user, onNavigate, logout, theme, setTheme, isAdministrator, navigation }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const navigate = id => { setMenuOpen(false); onNavigate(id) }
  return <div className="app-shell" data-theme={theme}>
    <aside className={`sidebar ${menuOpen ? 'open' : ''}`}><div className="brand"><span className="brand-mark">◢</span><div><strong>PIGNUS</strong><small>GUARDIANES POR NATURALEZA</small></div></div><p className="nav-label">MÓDULOS</p><nav>{navigation.map(([id, icon, label]) => <button title={`Abrí el módulo ${label} desde el menú de navegación.`} key={id} className={id === 'help' ? 'active' : ''} onClick={() => navigate(id)}><Icon name={icon} />{label}</button>)}</nav><div className="sidebar-bottom">v2.0 · Agenda técnica</div></aside>
    {menuOpen && <button title="Cerrá el menú lateral y volvé a la ayuda." className="backdrop" aria-label="Cerrar menú" onClick={() => setMenuOpen(false)} />}
    <main><header className="topbar"><button title="Abrí el menú lateral para elegir otro módulo." className="mobile-menu" onClick={() => setMenuOpen(true)}><Icon name="menu" /></button><div className="page-heading"><span>PIGNUS</span><i /><b>Centro de ayuda</b></div><div className="profile"><button className="theme-toggle" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} title={theme === 'light' ? 'Cambiá la plataforma a colores oscuros para reducir el brillo.' : 'Cambiá la plataforma a colores claros.'}><Icon name={theme === 'light' ? 'moon' : 'sun'} /></button><span className="profile-avatar">{String(user?.name || 'U').split(' ').map(part => part[0]).slice(0, 2).join('').toUpperCase()}</span><span>{user?.name}</span><RefreshButton /><button title="Cerrá tu sesión; necesitarás tus credenciales para volver a ingresar." className="logout-button" onClick={logout}><Icon name="logout" size={17} /><span>Cerrar sesión</span></button></div></header><section className="content"><HelpCenter onNavigate={onNavigate} isAdministrator={isAdministrator} allowedModules={navigation.map(([id]) => id)} /></section></main>
  </div>
}

export function TechnicianHelpCenter({ onNavigate }) {
  return <HelpCenter onNavigate={onNavigate} technicianOnly />
}

export function HelpCenter({ onNavigate, isAdministrator = false, allowedModules = [], technicianOnly = false }) {
  const allowedModuleKey = allowedModules.join('|')
  const available = useMemo(() => MODULES.filter(item => technicianOnly
    ? TECHNICIAN_MODULE_IDS.has(item.id)
    : (isAdministrator || !item.adminOnly) && (!item.module || allowedModules.includes(item.module))), [isAdministrator, allowedModuleKey, technicianOnly])
  const faqEntries = technicianOnly ? TECHNICIAN_FAQ : FAQ
  const [query, setQuery] = useState('')
  const [active, setActive] = useState(technicianOnly ? 'technician' : 'start')
  const [open, setOpen] = useState(technicianOnly ? 'technician-0' : 'start-0')
  const selected = available.find(item => item.id === active) || available[0]
  const searchResults = useMemo(() => {
    const term = normalize(query).trim()
    if (!term) return []
    const moduleResults = available.flatMap(section => section.articles
      .map((article, index) => ({ ...article, section, index }))
      .filter(item => normalize(`${item.section.title} ${item.title} ${item.intro || ''} ${item.body || ''} ${(item.steps || []).join(' ')} ${item.note || ''}`).includes(term)))
    const faqSection = { id: 'faq', icon: 'help', title: 'Preguntas frecuentes' }
    const faqResults = faqEntries
      .map(([title, body], index) => ({ title, body, section: faqSection, index }))
      .filter(item => normalize(`${item.title} ${item.body}`).includes(term))
    return [...moduleResults, ...faqResults]
  }, [available, faqEntries, query])
  const choose = (sectionId, articleIndex = 0) => { setActive(sectionId); setOpen(`${sectionId}-${articleIndex}`); setQuery('') }
  const visibleArticles = selected?.articles || []
  return <div className="help-center">
    <header className="help-hero">
      <ModuleIntroduction><p className="eyebrow">GUÍAS Y PREGUNTAS FRECUENTES</p><h1>Centro de ayuda</h1><span className="help-updated">Actualizado · 21 de octubre de 2026</span><p>{technicianOnly ? 'Consultá las funciones disponibles en tu perfil técnico.' : 'Encontrá instrucciones simples para completar cada tarea con seguridad.'}</p></ModuleIntroduction>
      <label className="help-search"><Icon name="search" size={19} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="¿Qué necesitás hacer?" autoComplete="off" />{query && <button title="Borrá el texto de búsqueda para volver a consultar toda la ayuda." onClick={() => setQuery('')} aria-label="Limpiar búsqueda"><Icon name="close" size={15} /></button>}</label>
    </header>
    {query ? <section className="help-results data-card"><div className="help-section-title"><div><span>{searchResults.length}</span><h2>Resultados para “{query}”</h2></div></div>{searchResults.length ? searchResults.map(result => <button title="Abrí el artículo de ayuda encontrado en la búsqueda." className="help-result" key={`${result.section.id}-${result.index}`} onClick={() => choose(result.section.id, result.index)}><Icon name={result.section.icon} /><span><b>{result.title}</b><small>{result.section.title}</small></span><i>Ver respuesta →</i></button>) : <div className="help-empty"><Icon name="search" size={30} /><h3>No encontramos una respuesta con esas palabras</h3><p>Probá con términos como “feriado”, “guardia”, “cliente”, “técnico” o “copiar”.</p></div>}</section> : <div className="help-layout">
      <aside className="help-categories data-card"><h2>Temas de ayuda</h2>{available.map(item => <button title="Consultá los artículos de esta sección del centro de ayuda." className={item.id === selected?.id ? 'active' : ''} key={item.id} onClick={() => { setActive(item.id); setOpen(`${item.id}-0`) }}><span><Icon name={item.icon} /></span><div><b>{item.title}</b><small>{item.summary}</small></div></button>)}<button title="Consultá las respuestas a las preguntas frecuentes." className={active === 'faq' ? 'active' : ''} onClick={() => { setActive('faq'); setOpen('faq-0') }}><span><Icon name="help" /></span><div><b>Preguntas frecuentes</b><small>Respuestas rápidas para situaciones habituales.</small></div></button></aside>
      <section className="help-content data-card">{active === 'faq' ? <><div className="help-section-title"><div><span><Icon name="help" /></span><div><p className="eyebrow">RESPUESTAS RÁPIDAS</p><h2>Preguntas frecuentes</h2></div></div></div><div className="help-articles">{faqEntries.map(([question, answer], index) => <HelpArticle key={question} id={`faq-${index}`} title={question} body={answer} open={open} setOpen={setOpen} />)}</div></> : <><div className="help-section-title"><div><span><Icon name={selected.icon} /></span><div><p className="eyebrow">GUÍA DEL MÓDULO</p><h2>{selected.title}</h2><p>{selected.summary}</p></div></div>{selected.module && <button title="Abrí el módulo relacionado con este artículo para realizar la gestión." className="secondary" onClick={() => onNavigate(selected.module)}>Ir al módulo <span>→</span></button>}</div><div className="help-articles">{visibleArticles.map((article, index) => <HelpArticle key={article.title} id={`${selected.id}-${index}`} {...article} open={open} setOpen={setOpen} />)}</div></>}</section>
    </div>}
    <section className="help-tip"><span>i</span><div><b>Consejo</b><p>{technicianOnly ? 'Antes de confirmar un estado, revisá el servicio y la observación: el cambio queda registrado con tu nombre y horario.' : 'Si una acción puede modificar o eliminar información, leé el mensaje de confirmación antes de continuar. El sistema explica qué datos serán afectados.'}</p></div></section>
  </div>
}

function HelpArticle({ id, title, intro, body, steps, note, open, setOpen }) {
  const expanded = open === id
  return <article className={expanded ? 'open' : ''}><button title="Desplegá u ocultá las instrucciones de este artículo de ayuda." onClick={() => setOpen(expanded ? '' : id)} aria-expanded={expanded}><span>{title}</span><i>{expanded ? '−' : '+'}</i></button>{expanded && <div className="help-answer">{intro && <p>{intro}</p>}{body && <p>{body}</p>}{steps && <ol>{steps.map(step => <li key={step}>{step}</li>)}</ol>}{note && <div className="help-note"><b>Importante</b><span>{note}</span></div>}</div>}</article>
}
